// A shipped package that hands out CLASS INSTANCES: data on the object,
// methods on the prototype. `make` is protobufjs's `long` in miniature --
// `new Long(low, high, unsigned)` with `toNumber` on `Long.prototype` --
// and the rest are the other axes JS's [[Get]] has and an own-only read
// does not. Cases 4031, 4061 and 4062 drive them.
"use strict";

// The inherited ENUMERABLE method (`F.prototype.m = fn`, pre-class JS,
// and what esbuild leaves of a class in a downlevelled bundle).
function L(lo, hi, u) {
  this.low = 0 | lo;
  this.high = 0 | hi;
  this.unsigned = !!u;
}
L.prototype.toNumber = function () { return this.high * 4294967296 + this.low };
exports.make = function (lo, hi) { return new L(lo, hi, false) };

// The inherited NON-ENUMERABLE method -- what `class K { twice() {} }`
// actually installs. Object.keys(k) is [] for it in Node, and [[Get]]
// answers it all the same: `enumerable` is about ENUMERATION.
function K(v) { this.v = v }
Object.defineProperty(K.prototype, "twice", {
  value: function () { return this.v * 2 },
  enumerable: false, writable: true, configurable: true,
});
exports.makeK = function (v) { return new K(v) };

// An OWN non-enumerable data property. Own, so no prototype walk is
// involved -- but scr_dyn_obj_get does not see the hidden table either.
function H() {
  this.m = 1;
  Object.defineProperty(this, "n", { value: 5, enumerable: false });
}
exports.makeHidden = function () { return new H() };

// Shadowing: the OWN member must win over the prototype's.
function S() { this.tag = "own" }
S.prototype.tag = "proto";
exports.makeShadow = function () { return new S() };

// Two levels up.
function A() {}
function B() {}
B.prototype = Object.create(A.prototype);
A.prototype.deep = function () { return this.z };
exports.makeDeep = function (z) { var b = new B(); b.z = z; return b };

// A null-prototype dictionary inherits NOTHING -- the walk must stop.
exports.makeBare = function () { var o = Object.create(null); o.low = 1; return o };

// An ACCESSOR on the prototype. JS's [[Get]] runs the getter; the record
// walkers' borrow-only read cannot (case 4062).
function G() { this.low = 1 }
Object.defineProperty(G.prototype, "hi", {
  get: function () { return 42 }, enumerable: false, configurable: true,
});
exports.makeGetter = function () { return new G() };

// An inherited DATA member, with no function anywhere in the shape: the
// removal control for the union-arm cases (4061 vs 4062).
function D(z) { this.z = z }
D.prototype.w = 3;
exports.makeData = function (z) { return new D(z) };
